// miRBase links, generated by mirbase/build_mirbase_links.py.
// Curator rule: a miRNA is linked only when its ALSmiR name is identical to the
// miRBase mature name; every other miRNA gets no link.
import raw from "./mirbase_links.json";

interface MirbaseLinks {
  release: string;
  urlTemplate: string;
  links: Record<string, string>;
}

const data = raw as MirbaseLinks;

export const MIRBASE_RELEASE = data.release;

/** miRBase accession and page for an ALSmiR miRNA name, or null when the name is not an exact match. */
export function mirbaseLink(name: string): { accession: string; url: string } | null {
  const accession = data.links[name];
  return accession ? { accession, url: data.urlTemplate.replace("{accession}", accession) } : null;
}
